/* HEXA BATTLEGROUNDS setup — PART 74 OF 79. Run parts in order. Safe to re-run. */ insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, relay, attempts, time_limit, hint, explanation, points, coins, status) values ('mission-scales-14', 'scales', 'mission', 'Balance Scales', 'maths', 1, array['food','market','coffee','social','any']::text[], 'The canteen store-room scales are balanced. Scout sees them, Intel knows one weight, Decoder has the delivery note.', '{"scout":{"title":"The two scales","body":"Scale 1:  ☕☕   ⚖   🥥\nScale 2:  🥥☕☕   ⚖   💻","big":true},"intel":{"title":"Known weight","body":"One coffee mug ☕ weighs 4 kg."},"decoder":{"title":"Delivery note","body":"How many kg is this box?   ☕☕ + 🥥🥥 + 💻"}}'::jsonb, '[{"label":"Weight in kg","accept":["40"]}]'::jsonb, false, 3, 200, 'Work out B from scale 1, then C from scale 2, then add up the box.', 'coffee mug=4, coconut=8, laptop=16 → 40', null, 25, 'published'), ('mission-scales-15', 'scales', 'mission', 'Balance Scales', 'maths', 1, array['food','market','coffee','social','any']::text[], 'The canteen store-room scales are balanced. Scout sees them, Intel knows one weight, Decoder has the delivery note.', '{"scout":{"title":"The two scales","body":"Scale 1:  🍇🍇   ⚖   💻\nScale 2:  💻🍇   ⚖   🍌","big":true},"intel":{"title":"Known weight","body":"One grapes 🍇 weighs 5 kg."},"decoder":{"title":"Delivery note","body":"How many kg is this box?   🍇 + 🍌"}}'::jsonb, '[{"label":"Weight in kg","accept":["20"]}]'::jsonb, false, 3, 200, 'Work out B from scale 1, then C from scale 2, then add up the box.', 'grapes=5, laptop=10, banana=15 → 20', null, 25, 'published'), ('mission-scales-16', 'scales', 'mission', 'Balance Scales', 'maths', 1, array['food','market','coffee','social','any']::text[], 'The canteen store-room scales are balanced. Scout sees them, Intel knows one weight, Decoder has the delivery note.', '{"scout":{"title":"The two scales","body":"Scale 1:  💻💻💻   ⚖   🍇\nScale 2:  🍇💻   ⚖   🍌","big":true},"intel":{"title":"Known weight","body":"One laptop 💻 weighs 2 kg."},"decoder":{"title":"Delivery note","body":"How many kg is this box?   💻 + 🍇 + 🍌"}}'::jsonb, '[{"label":"Weight in kg","accept":["16"]}]'::jsonb, false, 3, 200, 'Work out B from scale 1, then C from scale 2, then add up the box.', 'laptop=2, grapes=6, banana=8 → 16', null, 25, 'published'), ('mission-scales-17', 'scales', 'mission', 'Balance Scales', 'maths', 1, array['food','market','coffee','social','any']::text[], 'The canteen store-room scales are balanced. Scout sees them, Intel knows one weight, Decoder has the delivery note.', '{"scout":{"title":"The two scales","body":"Scale 1:  🍇🍇🍇   ⚖   📦\nScale 2:  📦🍇   ⚖   💻","big":true},"intel":{"title":"Known weight","body":"One grapes 🍇 weighs 3 kg."},"decoder":{"title":"Delivery note","body":"How many kg is this box?   🍇🍇 + 💻"}}'::jsonb, '[{"label":"Weight in kg","accept":["18"]}]'::jsonb, false, 3, 200, 'Work out B from scale 1, then C from scale 2, then add up the box.', 'grapes=3, parcel=9, laptop=12 → 18', null, 25, 'published'), ('mission-scales-18', 'scales', 'mission', 'Balance Scales', 'maths', 1, array['food','market','coffee','social','any']::text[], 'The canteen store-room scales are balanced. Scout sees them, Intel knows one weight, Decoder has the delivery note.', '{"scout":{"title":"The two scales","body":"Scale 1:  🍍🍍🍍   ⚖   🍉\nScale 2:  🍉🍍🍍   ⚖   🍌","big":true},"intel":{"title":"Known weight","body":"One pineapple 🍍 weighs 6 kg."},"decoder":{"title":"Delivery note","body":"How many kg is this box?   🍍🍍 + 🍉🍉 + 🍌"}}'::jsonb, '[{"label":"Weight in kg","accept":["78"]}]'::jsonb, false, 3, 200, 'Work out B from scale 1, then C from scale 2, then add up the box.', 'pineapple=6, melon=18, banana=30 → 78', null, 25, 'published'), ('mission-scales-19', 'scales', 'mission', 'Balance Scales', 'maths', 1, array['food','market','coffee','social','any']::text[], 'The canteen store-room scales are balanced.