 = excluded.status, version = case when mission_templates.clues is distinct from excluded.clues or mission_templates.parts is distinct from excluded.parts then mission_templates.version + 1 else mission_templates.version end, updated_at = now(); insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, relay, attempts, time_limit, hint, explanation, points, coins, status) values ('mission-qwerty-0', 'qwerty', 'mission', 'Keyboard Cipher', 'cipher', 1, array['office','learning','helpdesk','stg','any']::text[], 'A message was typed with the hands in the wrong place on the keyboard. Scout has the message, Intel knows how far the hands slipped, Decoder has the keyboard.', '{"scout":{"title":"Scrambled message","body":"AWECWE","big":true},"intel":{"title":"Where the hands were","body":"The typist''s hands were 1 key to the LEFT of where they should be, on the same row. Each row wraps around at the ends."},"decoder":{"title":"The keyboard","body":"Top row:     Q W E R T Y U I O P\nMiddle row:  A S D F G H J K L\nBottom row:  Z X C V B N M"}}'::jsonb, '[{"label":"The real word","accept":["SERVER"]}]'::jsonb, false, 3, 200, 'For each letter, find it on Decoder''s keyboard and move back the other way.', 'AWECWE shifted 1 → SERVER', null, 25, 'published'), ('mission-qwerty-1', 'qwerty', 'mission', 'Keyboard Cipher', 'cipher', 1, array['office','learning','helpdesk','stg','any']::text[], 'A message was typed with the hands in the wrong place on the keyboard. Scout has the message, Intel knows how far the hands slipped, Decoder has the keyboard.', '{"scout":{"title":"Scrambled message","body":"VAPIF","big":true},"intel":{"title":"Where the hands were","body":"The typist''s hands were 1 key to the RIGHT of where they should be, on the same row. Each row wraps around at the ends."},"decoder":{"title":"The keyboard","body":"Top row:     Q W E R T Y U I O P\nMiddle row:  A S D F G H J K L\nBottom row:  Z X C V B N M"}}'::jsonb, '[{"label":"The real word","accept":["CLOUD"]}]'::jsonb, false, 3, 200, 'For each letter, find it on Decoder''s keyboard and move back the other way.', 'VAPIF shifted -1 → CLOUD', null, 25, 'published'), ('mission-qwerty-2', 'qwerty', 'mission', 'Keyboard Cipher', 'cipher', 2, array['office','learning','helpdesk','stg','any']::text[], 'A message was typed with the hands in the wrong place on the keyboard. Scout has the message, Intel knows how far the hands slipped, Decoder has the keyboard.', '{"scout":{"title":"Scrambled message","body":"WIUKQZ","big":true},"intel":{"title":"Where the hands were","body":"The typist''s hands were 2 keys to the RIGHT of where they should be, on the same row. Each row wraps around at the ends."},"decoder":{"title":"The keyboard","body":"Top row:     Q W E R T Y U I O P\nMiddle row:  A S D F G H J K L\nBottom row:  Z X C V B N M"}}'::jsonb, '[{"label":"The real word","accept":["PYTHON"]}]'::jsonb, false, 3, 200, 'For each letter, find it on Decoder''s keyboard and move back the other way.', 'WIUKQZ shifted -2 → PYTHON', null, 25, 'published'), ('mission-qwerty-3', 'qwerty', 'mission', 'Keyboard Cipher', 'cipher', 2, array['office','learning','helpdesk','stg','any']::text[], 'A message was typed with the hands in the wrong place on the keyboard. Scout has the message, Intel knows how far the hands slipped, Decoder has the keyboard.', '{"scout":{"title":"Scrambled message","body":"CKZHTI","big":true},"intel":{"title":"Where the hands were","body":"The typist''s hands were 2 keys to the LEFT of where they should be, on the same row. Each row wraps around at the ends."},"decoder":{"title":"The keyboard","body":"Top row:     Q W E R T Y U I O P\nMiddle row:  A S D F G H J K L\nBottom row:  Z X C V B N M"}}'::jsonb, '[{"label":"The real word","accept":["BACKUP"]}]'::jsonb, false, 3, 200, 'For each letter, find it on Decoder''s keyboard and move back the other way.', 'CKZHTI shifted 2 → BACKUP', null, 25, 'published'), ('mission-qwerty-4', 'qwer